import{_ as a,a0 as p,w as i,s as u,ao as l,I as r,x as n,a1 as o,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"Linux有问必答：Ubuntu桌面上如何禁用默认的密钥环解锁提示 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：Ubuntu桌面上如何禁用默认的密钥环解锁提示 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：Ubuntu桌面上如何禁用默认的密钥环解锁提示 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：Ubuntu桌面上如何禁用默认的密钥环解锁提示 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150506 Linux FAQs with Answers--How to disable entering password for default keyring to unlock on Ubuntu desktop","title":"Linux有问必答：Ubuntu桌面上如何禁用默认的密钥环解锁提示","tag":"201506","desc":""},"relativePath":"201506/20150506 Linux FAQs with Answers--How to disable entering password for default keyring to unlock on Ubuntu desktop.md","filePath":"[post].md"}'),d={name:"201506/20150506 Linux FAQs with Answers--How to disable entering password for default keyring to unlock on Ubuntu desktop.md"};function m(f,t,b,k,g,x){const e=p("Link");return i(),u("div",null,[t[13]||(t[13]=l(`<h1 id="linux有问必答-ubuntu桌面上如何禁用默认的密钥环解锁提示" tabindex="-1">Linux有问必答：Ubuntu桌面上如何禁用默认的密钥环解锁提示 <a class="header-anchor" href="#linux有问必答-ubuntu桌面上如何禁用默认的密钥环解锁提示" aria-label="Permalink to “Linux有问必答：Ubuntu桌面上如何禁用默认的密钥环解锁提示”">​</a></h1><blockquote><p><strong>问题</strong>：当我启动我的Ubuntu桌面时，出现了一个弹出对话框，要求我输入密码来解锁默认的密钥环。我怎样才能禁用这个“解锁默认密钥环”弹出窗口，并自动解锁我的密钥环？</p></blockquote><p>密钥环是一个以加密方式存储你的登录信息的本地数据库。各种桌面应用（如浏览器、电子邮件客户端）使用密钥环来安全地存储并管理你的登录凭证、机密、密码、证书或密钥。对于那些需要检索存储在密钥环中的信息的应用程序，需要解锁该密钥环。</p><p>Ubuntu桌面所使用的GNOME密钥环被整合到了桌面登录中，该密钥环会在你验证进入桌面后自动解锁。但是，如果你设置了自动登录桌面或者是从休眠中唤醒，你默认的密钥环仍然可能“被锁定”的。在这种情况下，你会碰到这一提示：</p><blockquote><p>“输入密码来解锁密钥环‘默认密钥环’。某个应用想要访问密钥环‘默认密钥环’，但它被锁定了。”</p></blockquote><p><img src="https://farm9.staticflickr.com/8787/16716456754_309c39513c_o.png" alt=""></p><p>如果你想要避免在每次弹出对话框出现时输入密码来解锁默认密钥环，那么你可以这样做。</p><p>在做之前，请先了解禁用密码提示后可能出现的结果。通过自动解锁默认密钥环，你可以让任何使用你桌面的人无需知道你的密码而能获取你的密钥环（以及存储在密钥环中的任何信息）。</p><h3 id="禁用默认密钥环解锁密码" tabindex="-1">禁用默认密钥环解锁密码 <a class="header-anchor" href="#禁用默认密钥环解锁密码" aria-label="Permalink to “禁用默认密钥环解锁密码”">​</a></h3><p>打开Dash，然后输入“password”来启动“密码和密钥”应用。</p><p><img src="https://farm8.staticflickr.com/7709/17312949416_ed9c4fbe2d_b.jpg" alt=""></p><p>或者，使用seahorse命令从命令行启动图形界面。</p><pre><code>$ seahorse 
</code></pre><p>在左侧面板中，右击“默认密钥环”，并选择“修改密码”。</p><p><img src="https://farm8.staticflickr.com/7740/17159959750_ba5b675b00_b.jpg" alt=""></p><p>输入你的当前登录密码。</p><p><img src="https://farm8.staticflickr.com/7775/17347551135_ce09260818_b.jpg" alt=""></p><p>在设置“默认”密钥环新密码的密码框中留空。</p><p><img src="https://farm8.staticflickr.com/7669/17345663222_c9334c738b_c.jpg" alt=""></p><p>在询问是否不加密存储密码对话框中点击“继续”。</p><p><img src="https://farm8.staticflickr.com/7761/17152692309_ce3891a0d9_c.jpg" alt=""></p><p>搞定。从今往后，那个该死的解锁密钥环提示对话框再也不会来烦你了。</p><hr>`,23)),r("p",null,[t[1]||(t[1]=n("via: ",-1)),o(e,{href:"http://ask.xmodulo.com/disable-entering-password-unlock-default-keyring.html"},{default:s(()=>[...t[0]||(t[0]=[n("http://ask.xmodulo.com/disable-entering-password-unlock-default-keyring.html",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=n("作者：",-1)),o(e,{href:"http://ask.xmodulo.com/author/nanni"},{default:s(()=>[...t[2]||(t[2]=[n("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=n(" 译者：",-1)),o(e,{href:"https://github.com/GOLinux"},{default:s(()=>[...t[3]||(t[3]=[n("GOLinux",-1)])]),_:1}),t[7]||(t[7]=n(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原创翻译，",-1)),o(e,{href:"https://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[n("Linux中国",-1)])]),_:1}),t[12]||(t[12]=n(" 荣誉推出",-1))])])}const L=a(d,[["render",m]]);export{w as __pageData,L as default};
